import{_ as t,H as d,f as r,i as o}from"./chunks/framework.CBmkDW73.js";const _=JSON.parse('{"title":"仕様レビュアーゲート (Spec Reviewers)","description":"","frontmatter":{},"headers":[],"relativePath":"ja/skills/reviewers.md","filePath":"ja/skills/reviewers.md"}'),a={name:"ja/skills/reviewers.md"};function s(i,e,c,l,n,h){return d(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="仕様レビュアーゲート-spec-reviewers" tabindex="-1">仕様レビュアーゲート (Spec Reviewers) <a class="header-anchor" href="#仕様レビュアーゲート-spec-reviewers" aria-label="Permalink to &quot;仕様レビュアーゲート (Spec Reviewers)&quot;">​</a></h1><p>仕様レビュアープロトコル (<code>skills/references/reviewers.md</code>) は、<code>design</code> 段階で <code>plan</code> に渡す前に実行される並列レビューゲートを規定します。</p><h2 id="トリガーベースの動的選択" tabindex="-1">トリガーベースの動的選択 <a class="header-anchor" href="#トリガーベースの動的選択" aria-label="Permalink to &quot;トリガーベースの動的選択&quot;">​</a></h2><p>仕様の特徴に基づいてレビュアーが動的に選択されます：</p><table tabindex="0"><thead><tr><th>トリガー条件</th><th>起動されるレビュアー</th><th>検査役割</th></tr></thead><tbody><tr><td>常時（ベースライン）</td><td><code>spec-compliance</code></td><td>契約の完全性、明確なテスト基準、非物語的フォーマットを検証。</td></tr><tr><td>状態遷移 / 非同期処理</td><td><code>state-machine</code></td><td>状態マシンの完全性、不正遷移、タイムアウト、レースコンディションを検証。</td></tr><tr><td>クロスルール / 複数仕様</td><td><code>cross-rule</code></td><td>システムルール、既存仕様、不変条件との整合性を検証。</td></tr><tr><td>モジュール / リポジトリ横断</td><td><code>cross-module</code></td><td>契約境界、Schema 互換性、依存関係順序を検証。</td></tr><tr><td>クラッシュ / 復旧 / 永続化</td><td><code>safety</code></td><td>クラッシュ復旧、データ損失防止、冪等再試行、ロールバック安全性を検証。</td></tr><tr><td>実装の複雑性が高い</td><td><code>implementability</code></td><td>見積もり範囲内でタスクが明確に実行可能か、隠れた曖昧さがないかを評価。</td></tr></tbody></table><h2 id="並行実行と-coordinator-の統合評価" tabindex="-1">並行実行と Coordinator の統合評価 <a class="header-anchor" href="#並行実行と-coordinator-の統合評価" aria-label="Permalink to &quot;並行実行と Coordinator の統合評価&quot;">​</a></h2><ol><li><strong>並行起動</strong>: トリガーされたすべてのレビュアーが独立したサブエージェントとして並行実行されます。</li><li><strong>Coordinator の統合評価</strong>: 主エージェントが指摘事項を批判的に評価し、矛盾の解決、漏れの特定、深刻度の判定を行い、一度の変更で仕様書を修正します。レビュアーは助言を行い、Coordinator が決定を下します。</li></ol>',7)])])}const m=t(a,[["render",s]]);export{_ as __pageData,m as default};
